import Redis from 'ioredis';

const IS_PRODUCTION = process.env.NODE_ENV === 'production';

const redis = new Redis({
  host: process.env.REDIS_HOST ?? 'localhost',
  port: parseInt(process.env.REDIS_PORT ?? '6379', 10),
  password: process.env.REDIS_PASSWORD,
  db: IS_PRODUCTION ? 0 : 1,             // separate DB for dev
  lazyConnect: IS_PRODUCTION,             // lazy in prod to handle migrations
  connectTimeout: 5000,
  keepAlive: IS_PRODUCTION,               // detect dead connections
  maxRetriesPerRequest: IS_PRODUCTION ? 3 : null,
  retryStrategy: (times) => {
    if (times > 10) return null;          // give up after 10 retries
    return Math.min(times * 50, 2000);
  },
  // Tune for your workload
  enableOfflineQueue: !IS_PRODUCTION,
});

async function setWithTimeout(
  key: string,
  value: string,
  ttl: number
): Promise<void> {
  await redis.set(key, value, 'EX', ttl, 'NX');
}

// get with 50 ms timeout
async function getWithTimeout(
  key: string
): Promise<string | null> {
  return redis.get(key, { checkFrequency: 100 });
}
